export const BASE = 'ac718abdd13b6fdb4a3e78ee56c945815d360156';
export const sources = {
  "src/tabs/OptionsTab.jsx": "import { useState, useRef } from 'react';\nimport { Button } from '../components/common/Button';\nimport { KeyboardShortcutsModal } from '../components/StorySettingsModal/KeyboardShortcutsModal';\nimport { useEscapeKey } from '../hooks/useEscapeKey';\nimport { OPTION_SECTION_IDS, OptionsSectionNav } from './OptionsTab/OptionsSectionNav';\nimport { useOptionsSectionNav } from './OptionsTab/useOptionsSectionNav';\nimport { SaveSection } from './OptionsTab/SaveSection';\nimport { InterfaceSection } from './OptionsTab/InterfaceSection';\nimport { ProjectsMediaSection } from './OptionsTab/ProjectsMediaSection';\nimport { VoiceSection } from './OptionsTab/VoiceSection';\nimport { AiImagesSection } from './OptionsTab/AiImagesSection';\nimport { AdvancedSection } from './OptionsTab/AdvancedSection';\nimport { YoutubeSection } from './OptionsTab/YoutubeSection';\nimport { DiagnosticSection } from './OptionsTab/DiagnosticSection';\nimport './OptionsTab.css';\n\nexport function OptionsTab({\n  copyFilesEnabled,\n  onCopyFilesChange,\n  workspaceDir,\n  configuredWorkspaceDir = '',\n  onPickWorkspaceDir,\n  useWorkspaceForNewProjects = false,\n  onUseWorkspaceForNewProjectsChange = null,\n  onConsolidateProject,\n  autoSaveEnabled,\n  onAutoSaveChange,\n  autoSaveBackupLimit,\n  onAutoSaveBackupLimitChange,\n  themePreference,\n  onThemePreferenceChange,\n  xttsSettings,\n  onUpdateXttsSettings,\n  sdSettings,\n  onUpdateSdSettings,\n  keyboardShortcuts,\n  onUpdateKeyboardShortcuts,\n  onBackToHome,\n  verboseLogging = false,\n  onVerboseLoggingChange = null,\n  onCopyLogPath = null,\n  onResolveLogPath = null,\n  project = null,\n  asModal = false,\n  onClose = null,\n}) {\n  const [shortcutsOpen, setShortcutsOpen] = useState(false);\n\n  // En modale : Escape ferme les Préférences. La modale des raccourcis, montée\n  // par-dessus, s'enregistre après et prend donc le dessus dans la pile Escape.\n  useEscapeKey(asModal, onClose);\n  const screenRef = useRef(null);\n  const {\n    activeSectionId,\n    sectionClass,\n    registerSection,\n    scrollToSection,\n  } = useOptionsSectionNav({ sectionIds: OPTION_SECTION_IDS, screenRef, remountKey: asModal });\n  const displayedWorkspaceDir = configuredWorkspaceDir || workspaceDir || '';\n\n  const content = (\n    <div className={`opts-screen${asModal ? ' is-modal' : ''}`} ref={screenRef}>\n      {onBackToHome && (\n        <div className=\"opts-back-row\">\n          <Button onClick={onBackToHome}>\n            Retour à l'accueil\n          </Button>\n        </div>\n      )}\n      <div className=\"opts-layout\">\n        <OptionsSectionNav activeSectionId={activeSectionId} onNavigate={scrollToSection} />\n        <div className=\"opts-content\">\n          <SaveSection\n            className={sectionClass('save')}\n            sectionRef={registerSection('save')}\n            autoSaveEnabled={autoSaveEnabled}\n            onAutoSaveChange={onAutoSaveChange}\n            autoSaveBackupLimit={autoSaveBackupLimit}\n            onAutoSaveBackupLimitChange={onAutoSaveBackupLimitChange}\n          />\n          <InterfaceSection\n            className={sectionClass('interface')}\n            sectionRef={registerSection('interface')}\n            themePreference={themePreference}\n            onThemePreferenceChange={onThemePreferenceChange}\n            onOpenShortcuts={() => setShortcutsOpen(true)}\n          />\n          <ProjectsMediaSection\n            className={sectionClass('projects-media')}\n            sectionRef={registerSection('projects-media')}\n            useWorkspaceForNewProjects={useWorkspaceForNewProjects}\n            onUseWorkspaceForNewProjectsChange={onUseWorkspaceForNewProjectsChange}\n            displayedWorkspaceDir={displayedWorkspaceDir}\n            onPickWorkspaceDir={onPickWorkspaceDir}\n            copyFilesEnabled={copyFilesEnabled}\n            onCopyFilesChange={onCopyFilesChange}\n            onConsolidateProject={onConsolidateProject}\n            project={project}\n          />\n          <VoiceSection\n            className={sectionClass('xtts')}\n            sectionRef={registerSection('xtts')}\n            xttsSettings={xttsSettings}\n            onUpdateXttsSettings={onUpdateXttsSettings}\n          />\n          <AiImagesSection\n            className={sectionClass('comfyui')}\n            sectionRef={registerSection('comfyui')}\n            sdSettings={sdSettings}\n            onUpdateSdSettings={onUpdateSdSettings}\n          />\n          <AdvancedSection\n            className={sectionClass('advanced')}\n            sectionRef={registerSection('advanced')}\n          />\n          <YoutubeSection\n            className={sectionClass('youtube')}\n            sectionRef={registerSection('youtube')}\n          />\n          <DiagnosticSection\n            className={sectionClass('diagnostic')}\n            sectionRef={registerSection('diagnostic')}\n            verboseLogging={verboseLogging}\n            onVerboseLoggingChange={onVerboseLoggingChange}\n            onCopyLogPath={onCopyLogPath}\n            onResolveLogPath={onResolveLogPath}\n          />\n        </div>\n      </div>\n    </div>\n  );\n\n  if (asModal) {\n    return (\n      <>\n        <div className=\"modal-overlay\" onClick={onClose}>\n          <div className=\"modal-box opts-modal-box\" onClick={(e) => e.stopPropagation()}>\n            <div className=\"modal-header\">\n              <span>Préférences</span>\n              <Button variant=\"icon\" className=\"modal-close\" onClick={onClose}>×</Button>\n            </div>\n            {content}\n          </div>\n        </div>\n        {shortcutsOpen && (\n          <KeyboardShortcutsModal\n            shortcuts={keyboardShortcuts}\n            onChange={onUpdateKeyboardShortcuts}\n            onClose={() => setShortcutsOpen(false)}\n          />\n        )}\n      </>\n    );\n  }\n\n  return (\n    <div className=\"screen visible\">\n      {content}\n      {shortcutsOpen && (\n        <KeyboardShortcutsModal\n          shortcuts={keyboardShortcuts}\n          onChange={onUpdateKeyboardShortcuts}\n          onClose={() => setShortcutsOpen(false)}\n        />\n      )}\n    </div>\n  );\n}\n",
  "src/tabs/OptionsTab/AdvancedSection.jsx": "import {\n  PACK_AUDIO_EDGE_SILENCE_MAX_SECONDS,\n  PACK_AUDIO_EDGE_SILENCE_MIN_SECONDS,\n  PACK_AUDIO_EDGE_SILENCE_SECONDS,\n  normalizePackAudioEdgeSilence,\n} from '../../config/audioProcessing.js';\nimport { usePersistentState } from '../../hooks/usePersistentState';\nimport { KEYS } from '../../store/persistentSettings';\n\nconst SILENCE_CODEC = {\n  decode: (raw) => normalizePackAudioEdgeSilence(raw),\n  encode: (value) => String(normalizePackAudioEdgeSilence(value)),\n};\n\nfunction SilenceDurationRow({ value, onChange, label }) {\n  return (\n    <div className=\"opts-row\">\n      <div className=\"opts-row-info\">\n        <div className=\"opts-row-label\">{label}</div>\n        <div className=\"opts-row-sub\">\n          Durée en secondes, de {PACK_AUDIO_EDGE_SILENCE_MIN_SECONDS} à {PACK_AUDIO_EDGE_SILENCE_MAX_SECONDS}.\n        </div>\n      </div>\n      <input\n        className=\"xtts-input opts-number\"\n        type=\"number\"\n        min={PACK_AUDIO_EDGE_SILENCE_MIN_SECONDS}\n        max={PACK_AUDIO_EDGE_SILENCE_MAX_SECONDS}\n        step=\"0.1\"\n        value={value}\n        onChange={(event) => onChange(normalizePackAudioEdgeSilence(event.target.value))}\n      />\n    </div>\n  );\n}\n\nexport function AdvancedSection({ className, sectionRef }) {\n  const [leadingSilenceSeconds, setLeadingSilenceSeconds] = usePersistentState(\n    KEYS.PACK_LEADING_SILENCE_SECONDS,\n    PACK_AUDIO_EDGE_SILENCE_SECONDS,\n    SILENCE_CODEC,\n  );\n  const [trailingSilenceSeconds, setTrailingSilenceSeconds] = usePersistentState(\n    KEYS.PACK_TRAILING_SILENCE_SECONDS,\n    PACK_AUDIO_EDGE_SILENCE_SECONDS,\n    SILENCE_CODEC,\n  );\n\n  return (\n    <section id=\"advanced\" className={className} ref={sectionRef}>\n      <div className=\"opts-card-title\">Silences audio</div>\n      <SilenceDurationRow\n        label=\"Silence au début\"\n        value={leadingSilenceSeconds}\n        onChange={setLeadingSilenceSeconds}\n      />\n      <SilenceDurationRow\n        label=\"Silence à la fin\"\n        value={trailingSilenceSeconds}\n        onChange={setTrailingSilenceSeconds}\n      />\n    </section>\n  );\n}\n",
  "src/tabs/OptionsTab/AiImagesSection.jsx": "import { useMessageLanguage } from '../../i18n/useMessageLanguage.js';\nimport {presentStoredError } from '../../i18n/userMessage.js';\nimport { useState, useEffect } from 'react';\nimport { invoke } from '@tauri-apps/api/core';\nimport { Button } from '../../components/common/Button';\nimport { Toggle } from '../../components/common/Toggle';\nimport { pickComfyWorkflowApiJson, pickComfyWorkflowConfigJson } from '../../hooks/useFileDialog';\nimport { isTauriRuntime } from '../../utils/tauriRuntime';\n\nexport function AiImagesSection({ className, sectionRef, sdSettings, onUpdateSdSettings }) {\n  useMessageLanguage();\n  const [sdProbe, setSdProbe] = useState({ state: 'idle', message: '' });\n  const [sdWorkflows, setSdWorkflows] = useState([]);\n  const [importApiPath, setImportApiPath] = useState(null);\n  const [importConfigPath, setImportConfigPath] = useState(null);\n  const [importing, setImporting] = useState(false);\n\n  useEffect(() => {\n    if (!isTauriRuntime()) return;\n\n    invoke('comfyui_list_workflows')\n      .then(setSdWorkflows)\n      .catch(() => {});\n  }, []);\n\n  async function handleTestSd() {\n    const launching = sdSettings?.autoStart && sdSettings?.launcherPath;\n    setSdProbe({\n      state: 'loading',\n      message: launching ? 'Démarrage de ComfyUI en cours… (peut prendre jusqu\\'à 3 minutes)' : 'Connexion à ComfyUI en cours…',\n    });\n    try {\n      await invoke('comfyui_check', { settings: sdSettings });\n      setSdProbe({ state: 'ok', message: 'ComfyUI accessible et prêt.' });\n    } catch (e) {\n      setSdProbe({ state: 'error', message: e });\n    }\n  }\n\n  async function handlePickApiJson() {\n    const result = await pickComfyWorkflowApiJson();\n    if (result) setImportApiPath(result);\n  }\n\n  async function handlePickConfigJson() {\n    const result = await pickComfyWorkflowConfigJson();\n    if (result) setImportConfigPath(result);\n  }\n\n  async function handleImportWorkflow() {\n    if (!importApiPath || !importConfigPath) return;\n    setImporting(true);\n    try {\n      const wf = await invoke('comfyui_import_workflow', {\n        apiJsonPath: importApiPath,\n        configJsonPath: importConfigPath,\n      });\n      setSdWorkflows(prev => [...prev.filter(w => w.id !== wf.id), wf]);\n      setImportApiPath(null);\n      setImportConfigPath(null);\n    } catch (e) {\n      setSdProbe({ state: 'error', message: { userMessage: e, prefix: \"Import échoué : \" } });\n    } finally {\n      setImporting(false);\n    }\n  }\n\n  async function handleDeleteWorkflow(workflowId) {\n    try {\n      await invoke('comfyui_delete_workflow', { workflowId });\n      setSdWorkflows(prev => prev.filter(w => w.id !== workflowId));\n    } catch (e) {\n      setSdProbe({ state: 'error', message: { userMessage: e, prefix: \"Suppression échouée : \" } });\n    }\n  }\n\n  return (\n    <section id=\"comfyui\" className={className} ref={sectionRef}>\n      <div className=\"opts-card-title\">Génération d'images IA — ComfyUI</div>\n      <div className=\"opts-row\">\n        <div className=\"opts-row-info\">\n          <div className=\"opts-row-label\">Activer la génération d'images IA</div>\n          <div className=\"opts-row-sub\">\n            Ajoute un bouton ✨ Générer IA sous chaque image dans l'éditeur.\n          </div>\n        </div>\n        <Toggle on={sdSettings?.aiImageGen} onChange={(v) => onUpdateSdSettings?.({ aiImageGen: v })} />\n      </div>\n\n      {sdSettings?.aiImageGen && (\n        <div className=\"xtts-settings\">\n          <div className=\"xtts-grid\">\n            <label className=\"xtts-label\">\n              URL du serveur ComfyUI\n              <input\n                className=\"xtts-input\"\n                value={sdSettings?.serverUrl ?? ''}\n                onChange={(e) => onUpdateSdSettings?.({ serverUrl: e.target.value })}\n                placeholder=\"http://127.0.0.1:8188\"\n              />\n            </label>\n            <label className=\"xtts-label\">\n              Script de démarrage ComfyUI\n              <input\n                className=\"xtts-input\"\n                value={sdSettings?.launcherPath ?? ''}\n                onChange={(e) => onUpdateSdSettings?.({ launcherPath: e.target.value })}\n                placeholder=\"Chemin vers start_comfyui.bat, start_comfyui.sh ou un launcher\"\n              />\n            </label>\n          </div>\n\n          <div className=\"opts-row opts-row--pt\">\n            <div className=\"opts-row-info\">\n              <div className=\"opts-row-label\">Démarrer ComfyUI automatiquement</div>\n              <div className=\"opts-row-sub\">\n                Lance le script de démarrage si ComfyUI ne répond pas au moment de générer.\n              </div>\n            </div>\n            <Toggle on={sdSettings?.autoStart} onChange={(v) => onUpdateSdSettings?.({ autoStart: v })} />\n          </div>\n\n          <div className=\"xtts-actions\">\n            <Button onClick={handleTestSd} disabled={sdProbe.state === 'loading'}>\n              {sdProbe.state === 'loading'\n                ? (sdSettings?.autoStart && sdSettings?.launcherPath ? 'Démarrage…' : 'Test en cours…')\n                : 'Tester ComfyUI'}\n            </Button>\n          </div>\n\n          {sdProbe.state !== 'idle' && (\n            <div className={`info-box ${sdProbe.state === 'error' ? 'warn' : ''}`}>\n              {presentStoredError(sdProbe.message)}\n            </div>\n          )}\n\n          {/* Gestion des workflows */}\n          <div className=\"sd-workflows-section\">\n            <div className=\"opts-row-label\" style={{ marginBottom: 8 }}>Workflows disponibles</div>\n            {sdWorkflows.length === 0 ? (\n              <div className=\"opts-row-sub\">Aucun workflow chargé.</div>\n            ) : (\n              <div className=\"sd-workflow-list\">\n                {sdWorkflows.map(wf => (\n                  <div key={wf.id} className=\"sd-workflow-item\">\n                    <div>\n                      <span className=\"sd-workflow-item-name\">{wf.name}</span>\n                      {!wf.isCustom && <span className=\"sd-workflow-item-tag\">intégré</span>}\n                    </div>\n                    {wf.isCustom && (\n                      <Button\n                        size=\"sm\"\n                        onClick={() => handleDeleteWorkflow(wf.id)}\n                      >\n                        Supprimer\n                      </Button>\n                    )}\n                  </div>\n                ))}\n              </div>\n            )}\n\n            <div className=\"sd-import-section\">\n              <div className=\"opts-row-label\" style={{ marginBottom: 6 }}>Importer un workflow custom</div>\n              <div className=\"sd-import-row\">\n                <Button size=\"sm\" onClick={handlePickApiJson}>\n                  {importApiPath ? '✓ API JSON' : 'Choisir *-api.json…'}\n                </Button>\n                <Button size=\"sm\" onClick={handlePickConfigJson}>\n                  {importConfigPath ? '✓ Config JSON' : 'Choisir *.config.json…'}\n                </Button>\n                <Button\n                  size=\"sm\"\n                  variant=\"primary-violet\"\n                  onClick={handleImportWorkflow}\n                  disabled={!importApiPath || !importConfigPath || importing}\n                >\n                  {importing ? 'Import…' : 'Importer'}\n                </Button>\n              </div>\n            </div>\n          </div>\n        </div>\n      )}\n    </section>\n  );\n}\n",
  "src/tabs/OptionsTab/DiagnosticSection.jsx": "import { useState, useEffect } from 'react';\nimport { Button } from '../../components/common/Button';\nimport { Toggle } from '../../components/common/Toggle';\n\nexport function DiagnosticSection({\n  className,\n  sectionRef,\n  verboseLogging,\n  onVerboseLoggingChange,\n  onCopyLogPath,\n  onResolveLogPath,\n}) {\n  const [copiedLogPath, setCopiedLogPath] = useState(null);\n  const [resolvedLogPath, setResolvedLogPath] = useState('');\n\n  useEffect(() => {\n    let cancelled = false;\n    if (!onResolveLogPath) return undefined;\n    onResolveLogPath().then((path) => {\n      if (!cancelled && path) setResolvedLogPath(path);\n    }).catch(() => {});\n    return () => { cancelled = true; };\n  }, [onResolveLogPath]);\n\n  async function handleCopyLogPathClick() {\n    if (!onCopyLogPath) return;\n    const file = await onCopyLogPath();\n    if (file) {\n      setCopiedLogPath(file);\n      setTimeout(() => setCopiedLogPath(null), 2200);\n    }\n  }\n\n  return (\n    <section id=\"diagnostic\" className={className} ref={sectionRef}>\n      <div className=\"opts-card-title\">Diagnostic</div>\n      <div className=\"opts-row\">\n        <div className=\"opts-row-info\">\n          <div className=\"opts-row-label\">Journalisation détaillée</div>\n          <div className=\"opts-row-sub\">\n            Enregistre les événements normaux (chargements, enregistrements, générations) dans le fichier de log,\n            en plus des erreurs. Utile pour partager le contexte d'un bug dans une issue GitHub.\n            Désactivé : seuls les avertissements et erreurs sont enregistrés.\n          </div>\n        </div>\n        <Toggle on={!!verboseLogging} onChange={onVerboseLoggingChange} />\n      </div>\n      <div className=\"opts-row\">\n        <div className=\"opts-row-info\">\n          <div className=\"opts-row-label\">Dossier des logs</div>\n          <div className=\"opts-row-sub\">\n            {resolvedLogPath ? (\n              <><code>{resolvedLogPath}</code> — fichier courant : <code>story-studio.log</code></>\n            ) : (\n              <>Dans le dossier de données de Story Studio. Fichier courant : <code>story-studio.log</code>.</>\n            )}\n            {copiedLogPath ? (\n              <span style={{ color: 'var(--accent-2-text)', marginLeft: 6 }}>(copié)</span>\n            ) : null}\n          </div>\n        </div>\n        <Button onClick={handleCopyLogPathClick} disabled={!onCopyLogPath} style={{ flexShrink: 0 }}>\n          Copier le chemin\n        </Button>\n      </div>\n      <div className=\"opts-help\">\n        Le fichier peut contenir des chemins locaux (noms de fichiers, dossier utilisateur). Vérifie son contenu avant de le partager publiquement.\n      </div>\n    </section>\n  );\n}\n",
  "src/tabs/OptionsTab/InterfaceSection.jsx": "import { useTranslation } from 'react-i18next';\nimport { AVAILABLE_LANGUAGES, changeUiLanguage } from '../../i18n/language';\nimport { Button } from '../../components/common/Button';\nimport { Toggle } from '../../components/common/Toggle';\nimport { useSelectionOpensSettings } from '../../hooks/useSelectionOpensSettings';\nimport { writeSelectionOpensSettings } from '../../store/selectionOpensSettings';\nimport { THEME_OPTIONS } from '../../store/themePreference';\n\nconst LANGUAGE_LABEL_KEYS = {\n  fr: 'settings:interface.language.french',\n  en: 'settings:interface.language.english',\n  it: 'settings:interface.language.italian',\n  pseudo: 'settings:interface.language.pseudo',\n};\n\nexport function InterfaceSection({\n  className,\n  sectionRef,\n  themePreference,\n  onThemePreferenceChange,\n  onOpenShortcuts,\n}) {\n  const { t, i18n } = useTranslation('settings');\n  const selectionOpensSettings = useSelectionOpensSettings();\n  const languageCount = AVAILABLE_LANGUAGES.filter((language) => language !== 'pseudo').length;\n  return (\n    <section id=\"interface\" className={className} ref={sectionRef}>\n      <div className=\"opts-card-title\">{t('settings:interface.section.title')}</div>\n      {AVAILABLE_LANGUAGES.length > 1 && (\n        <div className=\"opts-row\">\n          <div className=\"opts-row-info\">\n            <label className=\"opts-row-label\" htmlFor=\"ui-language\">{t('settings:interface.language.label')}</label>\n            <div className=\"opts-row-sub\">{t('settings:interface.language.availableCount', { count: languageCount })}</div>\n          </div>\n          <select id=\"ui-language\" className=\"xtts-input opts-select\" value={i18n.language}\n            onChange={(event) => changeUiLanguage(event.target.value)}>\n            {AVAILABLE_LANGUAGES.map((language) => (\n              <option key={language} value={language}>{t(LANGUAGE_LABEL_KEYS[language])}</option>\n            ))}\n          </select>\n        </div>\n      )}\n      <div className=\"opts-row\">\n        <div className=\"opts-row-info\">\n          <div className=\"opts-row-label\">{t('settings:interface.theme.label')}</div>\n          <div className=\"opts-row-sub\">{t('settings:interface.theme.description')}</div>\n        </div>\n        <select\n          className=\"xtts-input opts-select\"\n          value={themePreference}\n          onChange={(event) => onThemePreferenceChange?.(event.target.value)}\n        >\n          {THEME_OPTIONS.map((option) => (\n            <option key={option.value} value={option.value}>{t(option.labelKey)}</option>\n          ))}\n        </select>\n      </div>\n      <div className=\"opts-row\">\n        <div className=\"opts-row-info\">\n          <div className=\"opts-row-label\">{t('settings:interface.selection.label')}</div>\n          <div className=\"opts-row-sub\">{t('settings:interface.selection.description')}</div>\n        </div>\n        <Toggle\n          on={selectionOpensSettings}\n          onChange={writeSelectionOpensSettings}\n          ariaLabel={t('settings:interface.selection.label')}\n        />\n      </div>\n      <div className=\"opts-row\">\n        <div className=\"opts-row-info\">\n          <div className=\"opts-row-label\">{t('settings:interface.shortcuts.label')}</div>\n          <div className=\"opts-row-sub\">{t('settings:interface.shortcuts.description')}</div>\n        </div>\n        <Button onClick={onOpenShortcuts}>\n          {t('common:action.edit.label')}\n        </Button>\n      </div>\n    </section>\n  );\n}\n",
  "src/tabs/OptionsTab/OptionsSectionNav.jsx": "import { useTranslation } from 'react-i18next';\n\nconst OPTION_GROUPS = [\n  {\n    labelKey: 'settings:navigation.general.label',\n    items: [\n      { id: 'save', labelKey: 'settings:navigation.save.label' },\n      { id: 'interface', labelKey: 'settings:interface.section.title' },\n      { id: 'projects-media', labelKey: 'settings:navigation.projectsMedia.label' },\n    ],\n  },\n  {\n    labelKey: 'settings:navigation.ai.label',\n    items: [\n      { id: 'xtts', labelKey: 'settings:navigation.xtts.label' },\n      { id: 'comfyui', labelKey: 'settings:navigation.comfyui.label' },\n    ],\n  },\n  {\n    labelKey: 'settings:navigation.advanced.label',\n    items: [\n      { id: 'advanced', labelKey: 'settings:navigation.silences.label' },\n      { id: 'youtube', labelKey: 'settings:navigation.youtube.label' },\n      { id: 'diagnostic', labelKey: 'settings:navigation.diagnostic.label' },\n    ],\n  },\n];\n\nexport const OPTION_SECTION_IDS = OPTION_GROUPS.flatMap((group) => group.items.map((item) => item.id));\n\nexport function OptionsSectionNav({ activeSectionId, onNavigate }) {\n  const { t } = useTranslation('settings');\n  return (\n    <nav className=\"opts-nav\" aria-label={t('settings:navigation.sections.label')}>\n      {OPTION_GROUPS.map((group) => (\n        <div className=\"opts-nav-group\" key={group.labelKey}>\n          <div className=\"opts-nav-group-title\">{t(group.labelKey)}</div>\n          <div className=\"opts-nav-items\">\n            {group.items.map((item) => (\n              <button\n                key={item.id}\n                type=\"button\"\n                className={`opts-nav-item${activeSectionId === item.id ? ' is-active' : ''}`}\n                onClick={() => onNavigate(item.id)}\n              >\n                {t(item.labelKey)}\n              </button>\n            ))}\n          </div>\n        </div>\n      ))}\n    </nav>\n  );\n}\n",
  "src/tabs/OptionsTab/PiperVoiceSettings.jsx": "import { Button } from '../../components/common/Button';\nimport { PIPER_LANGUAGE_OPTIONS } from '../../store/xttsSettings';\n\nexport function PiperVoiceSettings({\n  piperVoices,\n  piperProvision,\n  piperLanguage,\n  piperVoice,\n  piperSpeed,\n  updatePiperLanguage,\n  updatePiperVoice,\n  updatePiperSpeed,\n  preparePiperVoice,\n}) {\n  const visibleVoices = piperVoices.filter((voice) => voice.language === piperLanguage);\n  const voiceOptions = visibleVoices.length > 0\n    ? visibleVoices\n    : [{ id: piperVoice, label: piperVoice, installed: false }];\n\n  return (\n    <div className=\"xtts-settings\">\n      <div className=\"opts-row-sub\" style={{ marginBottom: 8 }}>\n        Piper ajoute un bouton texte → audio dans tous les champs audio. La voix est téléchargée\n        automatiquement au premier usage.\n      </div>\n      <div className=\"xtts-grid\">\n        <label className=\"xtts-label\">\n          Langue\n          <select\n            className=\"xtts-input\"\n            value={piperLanguage}\n            onChange={(e) => updatePiperLanguage(e.target.value)}\n            disabled={piperVoices.length === 0}\n          >\n            {PIPER_LANGUAGE_OPTIONS.map(({ value, label }) => (\n              <option key={value} value={value}>{label}</option>\n            ))}\n          </select>\n        </label>\n\n        <label className=\"xtts-label\">\n          Voix\n          <select\n            className=\"xtts-input\"\n            value={piperVoice}\n            onChange={(e) => updatePiperVoice(e.target.value)}\n            disabled={piperVoices.length === 0}\n          >\n            {voiceOptions.map((voice) => (\n              <option key={voice.id} value={voice.id}>\n                {voice.label}{voice.installed ? '' : ' — à télécharger'}\n              </option>\n            ))}\n          </select>\n        </label>\n\n        <label className=\"xtts-label\">\n          Vitesse ({piperSpeed.toFixed(2)}×)\n          <input\n            className=\"xtts-input\"\n            type=\"number\"\n            min=\"0.5\"\n            max=\"1.5\"\n            step=\"0.05\"\n            value={piperSpeed}\n            onChange={(e) => updatePiperSpeed(e.target.value)}\n          />\n        </label>\n      </div>\n\n      <div className=\"xtts-actions\">\n        <Button\n          onClick={preparePiperVoice}\n          disabled={piperProvision.state === 'loading' || piperVoices.length === 0}\n        >\n          {piperProvision.state === 'loading' ? 'Téléchargement…' : 'Préparer la voix maintenant'}\n        </Button>\n        <span className=\"opts-row-sub\">\n          Optionnel : prépare la voix sélectionnée à l’avance pour éviter l’attente au 1er usage.\n        </span>\n      </div>\n\n      {piperProvision.state !== 'idle' && (\n        <div className={`info-box ${piperProvision.state === 'error' ? 'warn' : ''}`}>\n          {piperProvision.message}\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "src/tabs/OptionsTab/ProjectsMediaSection.jsx": "import { useProjectMediaDirectory } from '../../hooks/useProjectMediaDirectory';\nimport { useState } from 'react';\nimport { Button } from '../../components/common/Button';\nimport { Toggle } from '../../components/common/Toggle';\nimport { formatFrenchCount } from '../../utils/frenchText.js';\n\nexport function ProjectsMediaSection({\n  className,\n  sectionRef,\n  useWorkspaceForNewProjects,\n  onUseWorkspaceForNewProjectsChange,\n  displayedWorkspaceDir,\n  onPickWorkspaceDir,\n  copyFilesEnabled,\n  onCopyFilesChange,\n  onConsolidateProject,\n  project,\n}) {\n  const importDirectory = useProjectMediaDirectory('fichiers-importes', { root: displayedWorkspaceDir, storage: project?.storage, ephemeral: false });\n  const [consolidating, setConsolidating] = useState(false);\n  const [consolidationResult, setConsolidationResult] = useState(null);\n\n  async function handleConsolidate() {\n    setConsolidating(true);\n    setConsolidationResult(null);\n    try {\n      const result = await onConsolidateProject?.();\n      if (result) setConsolidationResult(result);\n    } finally {\n      setConsolidating(false);\n    }\n  }\n\n  return (\n    <section id=\"projects-media\" className={className} ref={sectionRef}>\n      <div className=\"opts-card-title\">Gestion des projets et médias</div>\n      <div className=\"opts-row\">\n        <div className=\"opts-row-info\">\n          <div className=\"opts-row-label\">Utiliser un workspace pour les nouveaux projets</div>\n          <div className=\"opts-row-sub\">\n            Désactivé par défaut : les nouveaux projets commencent dans une session temporaire ; au premier enregistrement, leurs médias rejoignent l’emplacement de travail.\n          </div>\n        </div>\n        <Toggle on={!!useWorkspaceForNewProjects} onChange={onUseWorkspaceForNewProjectsChange} />\n      </div>\n      <div className=\"opts-row\">\n        <div className=\"opts-row-info\">\n          <div className=\"opts-row-label\">Emplacement de travail</div>\n          <div className=\"opts-row-sub\">\n            Emplacement de référence pour les projets enregistrés et les médias gérés.\n          </div>\n          <div className=\"opts-path-value\" title={displayedWorkspaceDir || ''}>\n            {displayedWorkspaceDir || 'Workspace en cours de résolution...'}\n          </div>\n        </div>\n        <Button onClick={onPickWorkspaceDir}>\n          Choisir\n        </Button>\n      </div>\n      <div className=\"opts-row\">\n        <div className=\"opts-row-info\">\n          <div className=\"opts-row-label\">Copier les fichiers importés dans l’emplacement de travail</div>\n          <div className=\"opts-row-sub\">\n            Copie chaque fichier importé (ZIP, 7z, audio, image) dans <strong>{importDirectory}</strong>.\n          </div>\n        </div>\n        <Toggle on={copyFilesEnabled} onChange={(v) => onCopyFilesChange?.(v)} />\n      </div>\n      <div className=\"opts-row\">\n        <div className=\"opts-row-info\">\n          <div className=\"opts-row-label\">Consolider le projet</div>\n          <div className=\"opts-row-sub\">\n            Copie le `.mbah` et tous les médias référencés dans un dossier cible, sans supprimer les originaux.\n          </div>\n        </div>\n        <Button onClick={handleConsolidate} disabled={consolidating || !project?.projectType}>\n          {consolidating ? 'Consolidation...' : 'Consolider'}\n        </Button>\n      </div>\n      {consolidationResult && (\n        <div className={`info-box info-box--spaced ${consolidationResult.errors?.length ? 'warn' : ''}`}>\n          Projet consolidé : {formatFrenchCount(\n            consolidationResult.copiedCount,\n            'média copié',\n            'médias copiés',\n          )}\n          {consolidationResult.errors?.length\n            ? `, ${formatFrenchCount(\n              consolidationResult.errors.length,\n              'fichier manquant',\n              'fichiers manquants',\n            )}.`\n            : '.'}\n        </div>\n      )}\n    </section>\n  );\n}\n",
  "src/tabs/OptionsTab/SaveSection.jsx": "import { Toggle } from '../../components/common/Toggle';\n\nexport function SaveSection({\n  className,\n  sectionRef,\n  autoSaveEnabled,\n  onAutoSaveChange,\n  autoSaveBackupLimit,\n  onAutoSaveBackupLimitChange,\n}) {\n  return (\n    <section id=\"save\" className={className} ref={sectionRef}>\n      <div className=\"opts-card-title\">Enregistrement</div>\n      <div className=\"opts-row\">\n        <div className=\"opts-row-info\">\n          <div className=\"opts-row-label\">Enregistrement automatique</div>\n          <div className=\"opts-row-sub\">Activé par défaut : enregistre le projet toutes les 5 minutes si des modifications sont en attente. Un projet jamais enregistré est copié dans le dossier sauvegardes/ de l'emplacement de travail.</div>\n        </div>\n        <Toggle on={autoSaveEnabled} onChange={onAutoSaveChange} />\n      </div>\n      {autoSaveEnabled && (\n        <div className=\"opts-row\">\n          <div className=\"opts-row-info\">\n            <div className=\"opts-row-label\">Versions de sécurité</div>\n            <div className=\"opts-row-sub\">Nombre de copies `.mbah` conservées avant chaque enregistrement automatique.</div>\n          </div>\n          <input\n            className=\"xtts-input opts-number\"\n            type=\"number\"\n            min=\"0\"\n            max=\"50\"\n            value={autoSaveBackupLimit}\n            onChange={(event) => onAutoSaveBackupLimitChange?.(Math.max(0, Math.min(50, Number(event.target.value) || 0)))}\n          />\n        </div>\n      )}\n      <div className=\"opts-help\">\n        Raccourcis : <strong>Ctrl+S</strong> pour enregistrer, <strong>Ctrl+Maj+S</strong> pour enregistrer sous\n      </div>\n    </section>\n  );\n}\n",
  "src/tabs/OptionsTab/VoiceSection.jsx": "import { PiperVoiceSettings } from './PiperVoiceSettings';\nimport { XttsVoiceSettings } from './XttsVoiceSettings';\nimport { usePiperVoiceOptions } from './usePiperVoiceOptions';\nimport { useXttsVoiceOptions } from './useXttsVoiceOptions';\n\nexport function VoiceSection({ className, sectionRef, xttsSettings, onUpdateXttsSettings }) {\n  const ttsBackend = xttsSettings.backend || 'piper';\n  const piperOptions = usePiperVoiceOptions({ xttsSettings, onUpdateXttsSettings });\n  const xttsOptions = useXttsVoiceOptions({ xttsSettings, onUpdateXttsSettings });\n\n  function handleTtsBackendChange(backend) {\n    // Sélectionner XTTS l'active (le moteur remplace l'ancien toggle d'activation).\n    onUpdateXttsSettings(backend === 'xtts' ? { backend, enabled: true } : { backend });\n  }\n\n  return (\n    <section id=\"xtts\" className={className} ref={sectionRef}>\n      <div className=\"opts-card-title\">Génération de voix locale</div>\n      <div className=\"opts-row\">\n        <div className=\"opts-row-info\">\n          <div className=\"opts-row-label\">Moteur de voix</div>\n          <div className=\"opts-row-sub\">\n            <strong>Piper</strong> fonctionne sans configuration (recommandé). <strong>XTTS</strong> est destiné\n            aux utilisateurs avancés (clonage de voix, serveur local).\n          </div>\n        </div>\n        <select\n          className=\"xtts-input opts-select\"\n          value={ttsBackend}\n          onChange={(e) => handleTtsBackendChange(e.target.value)}\n        >\n          <option value=\"piper\">Piper (défaut)</option>\n          <option value=\"xtts\">XTTS (avancé)</option>\n        </select>\n      </div>\n\n      {ttsBackend === 'piper' && (\n        <PiperVoiceSettings {...piperOptions} />\n      )}\n\n      {ttsBackend === 'xtts' && (\n        <XttsVoiceSettings\n          xttsSettings={xttsSettings}\n          {...xttsOptions}\n        />\n      )}\n    </section>\n  );\n}\n",
  "src/tabs/OptionsTab/XttsVoiceSettings.jsx": "import { Button } from '../../components/common/Button';\nimport { Toggle } from '../../components/common/Toggle';\nimport { formatFrenchCount } from '../../utils/frenchText.js';\n\nconst LANGUAGE_OPTIONS = [\n  { value: 'fr', label: 'Français' },\n  { value: 'en', label: 'English' },\n  { value: 'es', label: 'Español' },\n  { value: 'de', label: 'Deutsch' },\n  { value: 'it', label: 'Italiano' },\n  { value: 'pt', label: 'Português' },\n];\n\nexport function XttsVoiceSettings({\n  xttsSettings,\n  xttsProbe,\n  xttsVoices,\n  xttsVoicesLoaded,\n  xttsLogs,\n  favoriteVoices,\n  testXtts,\n  toggleXttsFavorite,\n  clearXttsFavorites,\n  updateServerUrl,\n  updateXttsDir,\n  updateLanguage,\n  updateAutoStart,\n  updateForceCpu,\n}) {\n  return (\n    <div className=\"xtts-settings\">\n      <div className=\"xtts-grid\">\n        <label className=\"xtts-label\">\n          URL du serveur XTTS\n          <input\n            className=\"xtts-input\"\n            value={xttsSettings.serverUrl}\n            onChange={(e) => updateServerUrl(e.target.value)}\n            placeholder=\"http://127.0.0.1:8020\"\n          />\n        </label>\n\n        <label className=\"xtts-label\">\n          Dossier XTTS\n          <input\n            className=\"xtts-input\"\n            value={xttsSettings.xttsDir}\n            onChange={(e) => updateXttsDir(e.target.value)}\n            placeholder=\"Dossier contenant server.py, venv, models et voices\"\n          />\n        </label>\n\n        <label className=\"xtts-label\">\n          Langue par défaut\n          <select\n            className=\"xtts-input\"\n            value={xttsSettings.language}\n            onChange={(e) => updateLanguage(e.target.value)}\n          >\n            {LANGUAGE_OPTIONS.map(({ value, label }) => (\n              <option key={value} value={value}>{label}</option>\n            ))}\n          </select>\n        </label>\n      </div>\n\n      <div className=\"opts-row opts-row--pt\">\n        <div className=\"opts-row-info\">\n          <div className=\"opts-row-label\">Démarrer XTTS automatiquement si le serveur est arrêté</div>\n          <div className=\"opts-row-sub\">\n            Story Studio lancera `server.py` depuis ton dossier XTTS si besoin.\n          </div>\n        </div>\n        <Toggle on={xttsSettings.autoStart} onChange={updateAutoStart} />\n      </div>\n\n      <div className=\"opts-row opts-row--pt\">\n        <div className=\"opts-row-info\">\n          <div className=\"opts-row-label\">Forcer le CPU (compatible ComfyUI simultané)</div>\n          <div className=\"opts-row-sub\">\n            XTTS s'exécute sur CPU — plus lent (~3×) mais libère le GPU pour ComfyUI.\n          </div>\n        </div>\n        <Toggle on={xttsSettings.forceCpu} onChange={updateForceCpu} />\n      </div>\n\n      <div className=\"xtts-actions\">\n        <Button onClick={testXtts} disabled={xttsProbe.state === 'loading'}>\n          {xttsProbe.state === 'loading' ? 'Test en cours…' : 'Tester et actualiser les voix'}\n        </Button>\n        <span className=\"opts-row-sub\">\n          {favoriteVoices.length > 0\n            ? `${formatFrenchCount(\n              favoriteVoices.length,\n              'voix favorite affichée dans la modale',\n              'voix favorites affichées dans la modale',\n            )}.`\n            : 'Aucune voix favorite : toutes les voix XTTS détectées seront proposées.'}\n        </span>\n      </div>\n\n      {xttsProbe.state !== 'idle' && (\n        <div className={`info-box ${xttsProbe.state === 'error' ? 'warn' : ''}`}>\n          {xttsProbe.message}\n        </div>\n      )}\n\n      {xttsLogs.length > 0 && (\n        <div className=\"xtts-log-panel\" aria-label=\"Journal XTTS\">\n          {xttsLogs.map((line, index) => (\n            <div key={`${index}-${line}`} className=\"xtts-log-line\">{line}</div>\n          ))}\n        </div>\n      )}\n\n      <div className=\"xtts-voices-panel\">\n        <div className=\"xtts-voices-header\">\n          <div>\n            <div className=\"opts-row-label\">Voix favorites</div>\n            <div className=\"opts-row-sub\">\n              Coche uniquement les voix que tu veux voir dans la modale de génération.\n            </div>\n          </div>\n          <Button onClick={clearXttsFavorites} disabled={favoriteVoices.length === 0}>\n            Tout afficher\n          </Button>\n        </div>\n\n        {!xttsVoicesLoaded ? (\n          <div className=\"xtts-voices-empty\">\n            Actualise les voix XTTS pour choisir tes favorites.\n          </div>\n        ) : xttsVoices.length === 0 ? (\n          <div className=\"xtts-voices-empty\">\n            Aucune voix retournée par XTTS.\n          </div>\n        ) : (\n          <div className=\"xtts-voice-list\">\n            {xttsVoices.map((voiceName) => (\n              <label key={voiceName} className=\"xtts-voice-item\">\n                <input\n                  type=\"checkbox\"\n                  checked={favoriteVoices.includes(voiceName)}\n                  onChange={() => toggleXttsFavorite(voiceName)}\n                />\n                <span>{voiceName}</span>\n              </label>\n            ))}\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}\n",
  "src/tabs/OptionsTab/YoutubeSection.jsx": "import { useMessageLanguage } from '../../i18n/useMessageLanguage.js';\nimport {presentStoredError } from '../../i18n/userMessage.js';\nimport { useState, useEffect } from 'react';\nimport { invoke } from '@tauri-apps/api/core';\nimport { listen } from '@tauri-apps/api/event';\nimport { Button } from '../../components/common/Button';\nimport { KEYS, read as readSetting, write } from '../../store/persistentSettings';\nimport { isTauriRuntime } from '../../utils/tauriRuntime';\nimport { releaseTauriListener } from '../../utils/tauriListener';\n\nexport function YoutubeSection({ className, sectionRef }) {\n  useMessageLanguage();\n  const [ytDlpPath, setYtDlpPath] = useState(() => readSetting(KEYS.YTDLP_CUSTOM_PATH, { defaultValue: '' }));\n  const [ytDlpUpdate, setYtDlpUpdate] = useState({ state: 'idle', message: '' });\n\n  // Reflète la progression de mise à jour de yt-dlp (téléchargement).\n  useEffect(() => {\n    if (!isTauriRuntime()) return undefined;\n    let cancelled = false;\n    let unlisten = null;\n    listen('youtube-log', (event) => {\n      if (cancelled) return;\n      setYtDlpUpdate((prev) => (prev.state === 'loading' ? { ...prev, message: event.payload } : prev));\n    }).then((fn) => {\n      if (cancelled) releaseTauriListener(fn);\n      else unlisten = fn;\n    }).catch(() => {});\n    return () => { cancelled = true; releaseTauriListener(unlisten); };\n  }, []);\n\n  function handleYtDlpPathChange(value) {\n    setYtDlpPath(value);\n    write(KEYS.YTDLP_CUSTOM_PATH, value);\n  }\n\n  async function handleUpdateYtDlp() {\n    setYtDlpUpdate({ state: 'loading', message: 'Mise à jour de yt-dlp…' });\n    try {\n      await invoke('update_ytdlp');\n      setYtDlpUpdate({ state: 'ok', message: 'yt-dlp est à jour.' });\n    } catch (e) {\n      setYtDlpUpdate({ state: 'error', message: e });\n    }\n  }\n\n  return (\n    <section id=\"youtube\" className={className} ref={sectionRef}>\n      <div className=\"opts-card-title\">YouTube (yt-dlp)</div>\n      <div className=\"opts-help\">\n        Le funnel « Pack depuis YouTube » télécharge automatiquement yt-dlp au premier usage et le\n        garde à jour, ainsi que le moteur JavaScript Deno (environ 40 Mo) dont yt-dlp a besoin pour\n        lire YouTube de façon fiable. YouTube bloquant les versions périmées, ces réglages ne servent\n        qu'en cas de souci.\n      </div>\n      <div className=\"opts-row\">\n        <div className=\"opts-row-info\">\n          <div className=\"opts-row-label\">Mettre à jour yt-dlp maintenant</div>\n          <div className=\"opts-row-sub\">\n            Force le téléchargement de la dernière version de yt-dlp et installe le moteur JavaScript\n            s'il manque. Utile si un import échoue avec un message de version obsolète.\n          </div>\n        </div>\n        <Button onClick={handleUpdateYtDlp} disabled={ytDlpUpdate.state === 'loading'} style={{ flexShrink: 0 }}>\n          {ytDlpUpdate.state === 'loading' ? 'Mise à jour…' : 'Mettre à jour'}\n        </Button>\n      </div>\n      {ytDlpUpdate.state !== 'idle' && (\n        <div className={`info-box ${ytDlpUpdate.state === 'error' ? 'warn' : ''}`}>\n          {presentStoredError(ytDlpUpdate.message)}\n        </div>\n      )}\n      <div className=\"opts-row\">\n        <div className=\"opts-row-info\">\n          <div className=\"opts-row-label\">Chemin yt-dlp personnalisé</div>\n          <div className=\"opts-row-sub\">\n            Laisse vide pour utiliser la version gérée automatiquement. Renseigne le chemin complet\n            d'un exécutable <code>yt-dlp.exe</code> sous Windows ou <code>yt-dlp</code> sous\n            Linux/macOS pour l'utiliser à la place (le téléchargement auto est alors ignoré).\n          </div>\n        </div>\n        <input\n          className=\"xtts-input\"\n          type=\"text\"\n          spellCheck={false}\n          placeholder=\"Chemin complet vers yt-dlp\"\n          value={ytDlpPath}\n          onChange={(event) => handleYtDlpPathChange(event.target.value)}\n          style={{ flex: 1, minWidth: 0 }}\n        />\n      </div>\n    </section>\n  );\n}\n",
  "src/tabs/OptionsTab/useOptionsSectionNav.js": "import { useEffect, useRef, useState } from 'react';\n\n// Scroll-spy des sections de préférences : suit la section visible dans le\n// conteneur scrollable, et pilote le clic de nav (scroll doux + flash de la\n// carte cible, avec suppression temporaire de l'observer pendant le scroll).\nexport function useOptionsSectionNav({ sectionIds, screenRef, remountKey }) {\n  const [activeSectionId, setActiveSectionId] = useState(sectionIds[0]);\n  const [highlightedSectionId, setHighlightedSectionId] = useState(null);\n  const sectionRefs = useRef({});\n  const observerSuppressedUntilRef = useRef(0);\n  const highlightTimerRef = useRef(null);\n  const highlightFrameRef = useRef(null);\n\n  useEffect(() => {\n    const root = screenRef.current;\n    const sections = sectionIds\n      .map((id) => sectionRefs.current[id])\n      .filter(Boolean);\n    if (!root || sections.length === 0 || typeof IntersectionObserver === 'undefined') return undefined;\n\n    const observer = new IntersectionObserver((entries) => {\n      if (Date.now() < observerSuppressedUntilRef.current) return;\n      const visibleEntries = entries\n        .filter((entry) => entry.isIntersecting)\n        .sort((a, b) => Math.abs(a.boundingClientRect.top) - Math.abs(b.boundingClientRect.top));\n      const nextId = visibleEntries[0]?.target?.id;\n      if (nextId) setActiveSectionId(nextId);\n    }, {\n      root,\n      rootMargin: '-12% 0px -70% 0px',\n      threshold: [0, 0.1, 0.35, 0.6],\n    });\n\n    sections.forEach((section) => observer.observe(section));\n    return () => observer.disconnect();\n  }, [remountKey, screenRef, sectionIds]);\n\n  useEffect(() => () => {\n    if (highlightTimerRef.current) window.clearTimeout(highlightTimerRef.current);\n    if (highlightFrameRef.current) window.cancelAnimationFrame(highlightFrameRef.current);\n  }, []);\n\n  function sectionClass(sectionId) {\n    return `opts-card${highlightedSectionId === sectionId ? ' is-highlighted' : ''}`;\n  }\n\n  function highlightSection(sectionId) {\n    if (highlightTimerRef.current) window.clearTimeout(highlightTimerRef.current);\n    if (highlightFrameRef.current) window.cancelAnimationFrame(highlightFrameRef.current);\n    setHighlightedSectionId(null);\n    highlightFrameRef.current = window.requestAnimationFrame(() => {\n      setHighlightedSectionId(sectionId);\n      highlightTimerRef.current = window.setTimeout(() => setHighlightedSectionId(null), 900);\n    });\n  }\n\n  function scrollToSection(sectionId) {\n    observerSuppressedUntilRef.current = Date.now() + 650;\n    sectionRefs.current[sectionId]?.scrollIntoView({ behavior: 'smooth', block: 'start' });\n    setActiveSectionId(sectionId);\n    highlightSection(sectionId);\n  }\n\n  function registerSection(sectionId) {\n    return (node) => { sectionRefs.current[sectionId] = node; };\n  }\n\n  return { activeSectionId, sectionClass, registerSection, scrollToSection };\n}\n",
  "src/tabs/OptionsTab/usePiperVoiceOptions.js": "import { useMessageLanguage } from '../../i18n/useMessageLanguage.js';\nimport {presentStoredError } from '../../i18n/userMessage.js';\nimport { useEffect, useState } from 'react';\nimport { invoke } from '@tauri-apps/api/core';\nimport { listen } from '@tauri-apps/api/event';\nimport { KEYS, write } from '../../store/persistentSettings';\nimport {\n  PIPER_DEFAULT_LANGUAGE,\n  PIPER_DEFAULT_VOICE,\n  piperDefaultVoiceForLanguage,\n  piperLanguageForVoice,\n} from '../../store/xttsSettings';\nimport { isTauriRuntime } from '../../utils/tauriRuntime';\nimport { releaseTauriListener } from '../../utils/tauriListener';\n\nexport function usePiperVoiceOptions({ xttsSettings, onUpdateXttsSettings }) {\n  useMessageLanguage();\n  const [piperVoices, setPiperVoices] = useState([]);\n  const [piperProvision, setPiperProvision] = useState({ state: 'idle', message: '' });\n\n  const piperLanguage = xttsSettings.piperLanguage || PIPER_DEFAULT_LANGUAGE;\n  const piperVoice = xttsSettings.piperVoice || PIPER_DEFAULT_VOICE;\n  const piperSpeed = Number.isFinite(Number(xttsSettings.piperSpeed)) && Number(xttsSettings.piperSpeed) > 0\n    ? Number(xttsSettings.piperSpeed)\n    : 1.0;\n\n  // Catalogue Piper (voix installées + à télécharger). Aucun réseau : lecture\n  // locale de l'état d'installation.\n  useEffect(() => {\n    if (!isTauriRuntime()) return;\n    invoke('piper_list_voices')\n      .then((status) => {\n        const voices = status?.voices || [];\n        setPiperVoices(voices);\n        const selected = voices.find((voice) => voice.id === piperVoice);\n        const language = selected?.language || piperLanguage;\n        const voice = selected?.language === language\n          ? selected.id\n          : piperDefaultVoiceForLanguage(voices, language);\n        if (language !== piperLanguage || voice !== piperVoice) {\n          write(KEYS.PIPER_LAST_VOICE, voice);\n          onUpdateXttsSettings({ piperLanguage: language, piperVoice: voice });\n        }\n      })\n      .catch(() => {});\n    // Le catalogue est chargé une fois ; les valeurs initiales servent uniquement\n    // à réconcilier une ancienne préférence avec le nouveau catalogue multilingue.\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  // Reflète les messages discrets du provisionnement Piper (téléchargement).\n  useEffect(() => {\n    if (!isTauriRuntime()) return undefined;\n    let cancelled = false;\n    let unlisten = null;\n    listen('piper-log', (event) => {\n      if (cancelled) return;\n      setPiperProvision((prev) => (prev.state === 'loading' ? { ...prev, message: event.payload } : prev));\n    }).then((fn) => {\n      if (cancelled) releaseTauriListener(fn);\n      else unlisten = fn;\n    }).catch(() => {});\n    return () => { cancelled = true; releaseTauriListener(unlisten); };\n  }, []);\n\n  function updatePiperLanguage(language) {\n    const voice = piperDefaultVoiceForLanguage(piperVoices, language);\n    write(KEYS.PIPER_LAST_VOICE, voice);\n    onUpdateXttsSettings({ piperLanguage: language, piperVoice: voice });\n  }\n\n  function updatePiperVoice(voice) {\n    const language = piperLanguageForVoice(piperVoices, voice, piperLanguage);\n    write(KEYS.PIPER_LAST_VOICE, voice);\n    onUpdateXttsSettings({ piperLanguage: language, piperVoice: voice });\n  }\n\n  function updatePiperSpeed(rawValue) {\n    const value = Number(rawValue);\n    if (Number.isFinite(value)) {\n      onUpdateXttsSettings({ piperSpeed: Math.max(0.5, Math.min(1.5, value)) });\n    }\n  }\n\n  async function preparePiperVoice() {\n    setPiperProvision({ state: 'loading', message: 'Préparation de la voix…' });\n    try {\n      await invoke('piper_ensure_voice', { voice: piperVoice });\n      setPiperVoices((prev) => prev.map((voice) => (\n        voice.id === piperVoice ? { ...voice, installed: true } : voice\n      )));\n      setPiperProvision({ state: 'ok', message: 'Voix prête.' });\n    } catch (e) {\n      setPiperProvision({ state: 'error', message: e });\n    }\n  }\n\n  return {\n    piperVoices,\n    piperProvision: { ...piperProvision, message: presentStoredError(piperProvision.message) },\n    piperLanguage,\n    piperVoice,\n    piperSpeed,\n    updatePiperLanguage,\n    updatePiperVoice,\n    updatePiperSpeed,\n    preparePiperVoice,\n  };\n}\n",
  "src/tabs/OptionsTab/useXttsVoiceOptions.js": "import { useMessageLanguage } from '../../i18n/useMessageLanguage.js';\nimport {presentTechnicalMessage, presentStoredError } from '../../i18n/userMessage.js';\nimport { useEffect, useState } from 'react';\nimport { invoke } from '@tauri-apps/api/core';\nimport { listen } from '@tauri-apps/api/event';\nimport { isTauriRuntime } from '../../utils/tauriRuntime';\nimport { formatFrenchCount } from '../../utils/frenchText.js';\nimport { releaseTauriListener } from '../../utils/tauriListener';\n\nexport function useXttsVoiceOptions({ xttsSettings, onUpdateXttsSettings }) {\n  useMessageLanguage();\n  const [xttsProbe, setXttsProbe] = useState({ state: 'idle', message: '' });\n  const [xttsVoices, setXttsVoices] = useState([]);\n  const [xttsVoicesLoaded, setXttsVoicesLoaded] = useState(false);\n  const [xttsLogs, setXttsLogs] = useState([]);\n\n  const favoriteVoices = Array.isArray(xttsSettings.favoriteVoices) ? xttsSettings.favoriteVoices : [];\n\n  useEffect(() => {\n    if (!isTauriRuntime()) return undefined;\n\n    let cancelled = false;\n    let unlisten = null;\n    listen('xtts-log', (event) => {\n      if (cancelled) return;\n      setXttsLogs((prev) => [...prev, event.payload].slice(-60));\n    }).then((fn) => {\n      if (cancelled) releaseTauriListener(fn);\n      else unlisten = fn;\n    }).catch(() => {});\n    return () => {\n      cancelled = true;\n      releaseTauriListener(unlisten);\n    };\n  }, []);\n\n  async function testXtts() {\n    setXttsProbe({ state: 'loading', message: 'Connexion à XTTS en cours…' });\n    setXttsLogs([`Test XTTS depuis ${xttsSettings.serverUrl}`]);\n    try {\n      const status = await invoke('xtts_get_status', { settings: xttsSettings });\n      const voices = status.voices || [];\n      setXttsVoices(voices);\n      setXttsVoicesLoaded(true);\n      const voicesLabel = formatFrenchCount(\n        voices.length,\n        'voix détectée',\n        'voix détectées',\n      );\n      const deviceLabel = status.device === 'cuda' ? 'GPU CUDA' : status.device === 'cpu' ? 'CPU' : 'device inconnu';\n      const modelLabel = status.model || 'modèle inconnu';\n      const voiceNames = voices.length > 0 ? ` • ${voices.join(', ')}` : '';\n      setXttsProbe({\n        state: 'ok',\n        message: `Serveur prêt • ${modelLabel} • ${deviceLabel} • ${voicesLabel}${voiceNames}`,\n      });\n    } catch (e) {\n      setXttsProbe({ state: 'error', message: e });\n    }\n  }\n\n  function toggleXttsFavorite(voiceName) {\n    const nextFavorites = favoriteVoices.includes(voiceName)\n      ? favoriteVoices.filter((voice) => voice !== voiceName)\n      : [...favoriteVoices, voiceName];\n    onUpdateXttsSettings({ favoriteVoices: nextFavorites });\n  }\n\n  function clearXttsFavorites() {\n    onUpdateXttsSettings({ favoriteVoices: [] });\n  }\n\n  function updateServerUrl(serverUrl) {\n    onUpdateXttsSettings({ serverUrl });\n  }\n\n  function updateXttsDir(xttsDir) {\n    onUpdateXttsSettings({ xttsDir });\n  }\n\n  function updateLanguage(language) {\n    onUpdateXttsSettings({ language });\n  }\n\n  function updateAutoStart(autoStart) {\n    onUpdateXttsSettings({ autoStart });\n  }\n\n  function updateForceCpu(forceCpu) {\n    onUpdateXttsSettings({ forceCpu });\n  }\n\n  return {\n    xttsProbe: { ...xttsProbe, message: presentStoredError(xttsProbe.message) },\n    xttsVoices,\n    xttsVoicesLoaded,\n    xttsLogs: xttsLogs.map((line) => presentTechnicalMessage(line)),\n    favoriteVoices,\n    testXtts,\n    toggleXttsFavorite,\n    clearXttsFavorites,\n    updateServerUrl,\n    updateXttsDir,\n    updateLanguage,\n    updateAutoStart,\n    updateForceCpu,\n  };\n}\n",
  "src/workspace/SettingsPanel.jsx": "import { useMemo } from 'react';\nimport { NodeEditorContent } from '../components/editors/NodeEditorContent';\nimport { EndNodeEditor } from '../components/editors/EndNodeEditor';\nimport { END_NODE_ID } from '../components/TreePanel/TreePanel';\nimport { collectAllStories } from '../store/projectModel';\nimport { useProjectActions } from '../store/ProjectActionsContext';\nimport '../components/editors/EditorPanel.css';\n\nexport function SettingsPanel({\n  node,\n  selectedId,\n  selectedIds,\n  project,\n  projectType,\n  allMenus,\n  projectIndex,\n  afterPlayFocus = null,\n  onAfterPlayFocusConsumed,\n  autoNextFocus = null,\n  onAutoNextFocusConsumed,\n  header = null,\n}) {\n  const {\n    onUpdateRoot,\n    onUpdateMedia,\n    onUpdateStoryAudio,\n    onUpdateGlobalOption,\n    onUpdateMenu,\n    onDeleteMenu,\n    onUpdateItem,\n    onDeleteItem,\n    onBulkUpdateItems,\n    onBulkDeleteItems,\n    onUpdateNightModeAudio,\n    onUpdateNightMode,\n    onUpdateNightModeReturn,\n    onUpdateNightModeHomeReturn,\n    onUpdateEndMessageAutoplay,\n    onRemoveEndNode,\n    onSelect,\n    onAttachStoryEndToGlobal,\n  } = useProjectActions();\n\n  const isMultiSelect = selectedIds && selectedIds.size > 1;\n  const allStories = useMemo(\n    () => collectAllStories(project, projectIndex),\n    [project, projectIndex],\n  );\n\n  let content = null;\n\n  if (!isMultiSelect && selectedId === END_NODE_ID) {\n    content = (\n      <EndNodeEditor\n        endNodeName={project.endNodeName || 'Message de fin'}\n        nightModeAudio={project.nightModeAudio}\n        nightModeActive={!!project.globalOptions?.nightMode}\n        nightModeReturn={project.nightModeReturn ?? null}\n        nightModeHomeReturn={project.nightModeHomeReturn ?? null}\n        projectName={project.projectName}\n        allMenus={allMenus}\n        allStories={allStories}\n        onUpdateNightModeAudio={onUpdateNightModeAudio}\n        onUpdateNightMode={onUpdateNightMode}\n        onUpdateNightModeReturn={onUpdateNightModeReturn}\n        onUpdateNightModeHomeReturn={onUpdateNightModeHomeReturn}\n        onUpdateEndMessageAutoplay={onUpdateEndMessageAutoplay}\n        onUpdateEndNodeName={(value) => onUpdateRoot?.({ endNodeName: value })}\n        onRemove={onRemoveEndNode}\n        project={project}\n        onExamineStory={onSelect}\n        onAttachStory={onAttachStoryEndToGlobal}\n      />\n    );\n  } else if (isMultiSelect) {\n    const count = selectedIds.size;\n    content = (\n      <>\n        <div className=\"multiselect-hint\">{count} éléments sélectionnés — modification groupée</div>\n        <NodeEditorContent\n          node={node}\n          selectedIds={selectedIds}\n          project={project}\n          projectIndex={projectIndex}\n          projectType={projectType}\n          allMenus={allMenus}\n          onUpdateRoot={onUpdateRoot}\n          onUpdateMedia={onUpdateMedia}\n          onUpdateStoryAudio={onUpdateStoryAudio}\n          onUpdateOption={onUpdateGlobalOption}\n          onUpdateMenu={onUpdateMenu}\n          onDeleteMenu={onDeleteMenu}\n          onUpdateItem={onUpdateItem}\n          onDeleteItem={onDeleteItem}\n          onBulkUpdateItems={onBulkUpdateItems}\n          onBulkDeleteItems={onBulkDeleteItems}\n          afterPlayFocus={afterPlayFocus}\n          onAfterPlayFocusConsumed={onAfterPlayFocusConsumed}\n          autoNextFocus={autoNextFocus}\n          onAutoNextFocusConsumed={onAutoNextFocusConsumed}\n        />\n      </>\n    );\n  } else if (node) {\n    content = (\n      <NodeEditorContent\n        node={node}\n        project={project}\n        projectIndex={projectIndex}\n        projectType={projectType}\n        allMenus={allMenus}\n        onUpdateRoot={onUpdateRoot}\n        onUpdateMedia={onUpdateMedia}\n        onUpdateStoryAudio={onUpdateStoryAudio}\n        onUpdateOption={onUpdateGlobalOption}\n        onUpdateMenu={onUpdateMenu}\n        onDeleteMenu={onDeleteMenu}\n        onUpdateItem={onUpdateItem}\n        onDeleteItem={onDeleteItem}\n        afterPlayFocus={afterPlayFocus}\n        onAfterPlayFocusConsumed={onAfterPlayFocusConsumed}\n        autoNextFocus={autoNextFocus}\n        onAutoNextFocusConsumed={onAutoNextFocusConsumed}\n      />\n    );\n  }\n\n  return (\n    <div className=\"settings-panel\">\n      {header}\n      <div className=\"settings-panel-body\">\n        {content}\n      </div>\n    </div>\n  );\n}\n",
  "src/workspace/SettingsPanelHeader.jsx": "import { ArrowRight, X } from '../components/icons/LucideLocal';\nimport { NodeIcon } from '../components/icons/NodeIcon.jsx';\nimport { hierarchicalNatureOf } from '../store/nodeIconVocabulary.js';\nimport { WORKSPACE_MODE_HIERARCHICAL } from '../store/projectWorkState.js';\nimport { END_NODE_ID, TYPE_LABELS } from '../components/diagram/flowDiagramLayout';\n\nfunction NodeTypeIcon({ type, icon }) {\n  // L'en-tete nomme toujours l'entree a cote de son dessin. Le repli est\n  // l'accueil.\n  return (\n    <NodeIcon\n      workspaceMode={WORKSPACE_MODE_HIERARCHICAL}\n      nature={hierarchicalNatureOf(type, { night: icon === 'moon' }) ?? 'root'}\n    />\n  );\n}\n\nfunction getHeaderData({ node, selectedId, selectedIds, project }) {\n  if (selectedIds?.size > 1) {\n    return {\n      type: 'multi',\n      title: `${selectedIds.size} éléments sélectionnés`,\n      badge: 'Modification groupée',\n      icon: null,\n    };\n  }\n  if (selectedId === END_NODE_ID) {\n    return {\n      type: END_NODE_ID,\n      title: project?.endNodeName || 'Message de fin',\n      badge: TYPE_LABELS[END_NODE_ID],\n      icon: project?.globalOptions?.nightMode ? 'moon' : 'stop',\n    };\n  }\n  if (!node) {\n    return {\n      type: 'root',\n      title: 'Réglages',\n      badge: 'Sélection',\n      icon: null,\n    };\n  }\n  const type = node.type === 'root' ? 'root' : node.type;\n  const rootTitle = project?.projectType === 'simple'\n    ? (project?.projectName || 'Mon histoire')\n    : (project?.rootName || project?.projectName || 'Menu racine');\n  // Badge du root : dépend du type de projet — « Histoire simple » en `simple`\n  // (le header est visible dans l'éditeur simple même sans diagramme),\n  // « Pack » sinon. « Histoire » seul serait ambigu avec TYPE_LABELS.story.\n  const rootBadge = project?.projectType === 'simple' ? 'Histoire simple' : 'Pack';\n  return {\n    type,\n    title: type === 'root' ? rootTitle : (node.name || TYPE_LABELS[type] || 'Réglages'),\n    badge: type === 'root' ? rootBadge : (TYPE_LABELS[type] || 'Réglages'),\n    icon: node.icon ?? null,\n  };\n}\n\nexport function SettingsPanelHeader({\n  node,\n  selectedId,\n  selectedIds,\n  project,\n  onClose = null,\n  dragHandleProps = {},\n}) {\n  const data = getHeaderData({ node, selectedId, selectedIds, project });\n\n  return (\n    <div className=\"settings-panel-header\" {...dragHandleProps}>\n      <div className=\"settings-panel-header-icon\" aria-hidden=\"true\">\n        {data.type === 'multi' ? <ArrowRight /> : <NodeTypeIcon type={data.type} icon={data.icon} />}\n      </div>\n      <div className=\"settings-panel-header-main\">\n        <div className=\"settings-panel-header-title\" title={data.title}>{data.title}</div>\n        <div className=\"settings-panel-header-badge\" title={data.badge}>{data.badge}</div>\n      </div>\n      {onClose ? (\n        <button\n          type=\"button\"\n          className=\"settings-panel-header-close\"\n          aria-label=\"Fermer les réglages\"\n          onClick={onClose}\n        >\n          <X aria-hidden=\"true\" />\n        </button>\n      ) : null}\n    </div>\n  );\n}\n",
  "src/hooks/useAppPreferences.js": "import { presentUserMessage } from '../i18n/userMessage.js';\nimport { invoke } from '@tauri-apps/api/core';\nimport { open as openDialog } from '@tauri-apps/plugin-dialog';\nimport { pickWorkspaceDir, consolidateProject, rememberRecentProject } from '../store/projectIO';\nimport { saveXttsSettings } from '../store/xttsSettings';\nimport { saveVerboseLoggingPref, verboseLevelName } from '../store/loggingPreference';\nimport { logger, setLogLevel } from '../utils/logger';\nimport { isTauriRuntime } from '../utils/tauriRuntime';\nimport { formatFrenchCount } from '../utils/frenchText.js';\nimport { collectEndMessagePresentations } from '../store/generatedNavigation';\n\n// Grappe « préférences & réglages » extraite d'AppContent : dossier workspace,\n// logging verbeux (+ chemins de log), consolidation projet,\n// message de fin (end node) et réglages XTTS. Ce sont les\n// actions qui alimentent la modale de Préférences (OptionsTab asModal) et les\n// éditeurs qui consomment onAddEndNode / onRemoveEndNode\n// (via ProjectActionsContext).\n//\n// Couplage assumé au cycle de sauvegarde : handleConsolidateProject pilote l'UI de\n// progression via setSaveProgress (qui vient de useSaveProgress, resté dans App.jsx).\n// Ce hook la REÇOIT en entrée, il ne recrée pas de progression — il doit donc être\n// appelé APRÈS useSaveProgress. sessionMode (useWorkSession) est lu pour ne pas\n// écraser le workspace d'une session éphémère.\n//\n// xttsSettings reste chez l'hôte (lu par la génération, ProjectContext, OptionsTab,\n// GenerateVoiceModal) : le hook ne reçoit que setXttsSettings et n'en duplique pas\n// l'état. Persistance exclusivement via les helpers dédiés (saveVerboseLoggingPref,\n// saveXttsSettings) et readSetting côté hôte, jamais localStorage en direct.\nexport function useAppPreferences({\n  store,\n  sessionMode,\n  setConfiguredWorkspaceDir,\n  setWorkspaceDirState,\n  setVerboseLoggingState,\n  setSaveProgress,\n  setRecentProjects,\n  setXttsSettings,\n  showErrorDialog,\n  showConfirmDialog,\n}) {\n  async function handlePickWorkspaceDir() {\n    const chosen = await pickWorkspaceDir();\n    if (chosen) {\n      logger.info(`workspace:switched path='${chosen}'`);\n      setConfiguredWorkspaceDir(chosen);\n      if (sessionMode !== 'ephemeral') {\n        setWorkspaceDirState(chosen);\n      }\n    }\n  }\n\n  async function handleVerboseLoggingChange(enabled) {\n    setVerboseLoggingState(enabled);\n    saveVerboseLoggingPref(enabled);\n    const level = verboseLevelName(enabled);\n    setLogLevel(level);\n    if (isTauriRuntime()) {\n      try { await invoke('set_log_level', { level }); }\n      catch (err) { logger.error('logging:set-level-error', err); }\n    }\n    logger.warn(`logging:level-changed level=${level}`);\n  }\n\n  function logDirOf(filePath) {\n    if (typeof filePath !== 'string' || !filePath) return null;\n    return filePath.replace(/[\\\\/][^\\\\/]*$/, '') || filePath;\n  }\n\n  async function handleResolveLogPath() {\n    if (!isTauriRuntime()) return null;\n    try {\n      const file = await invoke('get_current_log_file');\n      return logDirOf(file);\n    } catch (err) {\n      logger.error('logging:resolve-path-error', err);\n      return null;\n    }\n  }\n\n  async function handleCopyLogPath() {\n    if (!isTauriRuntime()) return null;\n    try {\n      const file = await invoke('get_current_log_file');\n      const dir = logDirOf(file);\n      if (!dir) return null;\n      await navigator.clipboard.writeText(dir);\n      return dir;\n    } catch (err) {\n      logger.error('logging:copy-path-error', err);\n      return null;\n    }\n  }\n\n  async function handleConsolidateProject() {\n    // À l'accueil, le store porte le projet par défaut : rien à consolider.\n    if (!store.project?.projectType) return null;\n    const destinationDir = await openDialog({\n      directory: true,\n      multiple: false,\n      title: 'Choisir le dossier de consolidation',\n    });\n    if (!destinationDir) return null;\n    setSaveProgress({ lines: ['Consolidation du projet...'], complete: false });\n    try {\n      const result = await consolidateProject(store.project, store.savePath, destinationDir, (step) => {\n        setSaveProgress(prev => prev ? { ...prev, lines: [...prev.lines, step] } : { lines: [step], complete: false });\n      });\n      const summary = formatFrenchCount(\n        result.copiedCount,\n        'fichier copié',\n        'fichiers copiés',\n      );\n      const warnings = result.errors.length > 0\n        ? `, ${formatFrenchCount(result.errors.length, 'erreur', 'erreurs')}`\n        : '';\n      setSaveProgress(prev => prev ? { ...prev, lines: [...prev.lines, `${summary}${warnings}`], complete: true } : null);\n      setTimeout(() => setSaveProgress(null), 2200);\n      if (result.path && result.project) {\n        setRecentProjects(rememberRecentProject(result.project, result.path));\n      }\n      if (result.errors.length > 0) {\n        showErrorDialog({\n          title: 'Projet consolidé',\n          message: `Projet consolidé avec des fichiers manquants :\\n\\n${result.errors.slice(0, 5).map((error) => `• ${error.path}\\n  ${presentUserMessage(error.error).message}`).join('\\n')}`,\n          variant: 'warning',\n        });\n      }\n      return result;\n    } catch (error) {\n      setSaveProgress(null);\n      showErrorDialog({\n        title: 'Consolidation impossible',\n        message: { userMessage: error, prefix: `Consolidation impossible : `, suffix: `` },\n      });\n      return null;\n    }\n  }\n\n  function handleAddEndNode() {\n    store.addGlobalEndMessage();\n    store.setSelectedId('end-node');\n  }\n\n  async function handleRemoveEndNode(options = {}) {\n    const presentations = collectEndMessagePresentations(store.project);\n    const globalCount = presentations.filter((item) => item.presentationKind === 'global').length;\n    const localCount = presentations.filter((item) => (\n      item.presentationKind === 'local_prompt' || item.presentationKind === 'local_sequence'\n    )).length;\n    if (!options?.skipConfirm) {\n      const confirmed = await showConfirmDialog({\n        title: 'Supprimer le message de fin',\n        message:\n          `Le message sera retiré de ${globalCount} histoire${globalCount > 1 ? 's' : ''}. `\n          + `${localCount} fin${localCount !== 1 ? 's locales seront' : ' locale sera'} conservée${localCount !== 1 ? 's' : ''}.`,\n        variant: 'warning',\n        okLabel: 'Supprimer',\n        okKind: 'danger',\n        cancelLabel: 'Annuler',\n      });\n      if (!confirmed) return false;\n    }\n\n    store.removeGlobalEndMessage();\n    return true;\n  }\n\n  function handleUpdateXttsSettings(fields) {\n    setXttsSettings(prev => {\n      const next = { ...prev, ...fields };\n      saveXttsSettings(next);\n      return next;\n    });\n  }\n\n  return {\n    handlePickWorkspaceDir,\n    handleVerboseLoggingChange,\n    handleResolveLogPath,\n    handleCopyLogPath,\n    handleConsolidateProject,\n    handleAddEndNode,\n    handleRemoveEndNode,\n    handleUpdateXttsSettings,\n  };\n}\n",
  "src/store/loggingPreference.js": "import { KEYS, read as readSetting, write as writeSetting, remove as removeSetting } from './persistentSettings';\n\nexport function loadVerboseLoggingPref() {\n  if (typeof window === 'undefined') return false;\n  try { return readSetting(KEYS.VERBOSE_LOGGING) === '1'; }\n  catch { return false; }\n}\n\nexport function saveVerboseLoggingPref(enabled) {\n  if (typeof window === 'undefined') return;\n  try {\n    if (enabled) writeSetting(KEYS.VERBOSE_LOGGING, '1');\n    else removeSetting(KEYS.VERBOSE_LOGGING);\n  } catch { /* ignore */ }\n}\n\nexport function verboseLevelName(enabled) {\n  return enabled ? 'info' : 'warn';\n}\n",
  "src/store/persistentSettings.js": "export const KEYS = Object.freeze({\n  RELEASE_NOTES_SEEN: 'storyStudio.releaseNotesSeen',\n  COPY_FILES: 'copyImportedFiles',\n  AUTOSAVE_ENABLED: 'autoSaveEnabled',\n  AUTOSAVE_DEFAULT_ON_APPLIED: 'storyStudio.autosaveDefaultOnApplied',\n  AUTOSAVE_BACKUP_LIMIT: 'autoSaveBackupLimit',\n  WORKSPACE_DIR: 'storyStudioWorkspaceDir',\n  USE_WORKSPACE_FOR_NEW_PROJECTS: 'storyStudio.useWorkspaceForNewProjects',\n  FREE_BOTTOM_PANEL_OPEN: 'storyStudio.free.bottomPanelOpen',\n  FREE_BOTTOM_PANEL_TAB: 'storyStudio.free.bottomPanelTab',\n  ADVANCED_BOTTOM_PANEL_OPEN: 'storyStudio.advanced.bottomPanelOpen',\n  ADVANCED_BOTTOM_PANEL_TAB: 'storyStudio.advanced.bottomPanelTab',\n  LAST_EXPORT_DIR: 'lastExportDir',\n  LAST_PACK_OUTPUT_DIR: 'lastPackOutputDir',\n  LAST_OPEN_PROJECT_DIR: 'lastOpenProjectDir',\n  LAST_SAVE_PROJECT_DIR: 'lastSaveProjectDir',\n  LAST_PROJECT_DIR: 'lastProjectDir',\n  LAST_IMPORT_DIR: 'lastImportDir',\n  LAST_IMAGE_IMPORT_DIR: 'lastImageImportDir',\n  LAST_AUDIO_IMPORT_DIR: 'lastAudioImportDir',\n  LAST_ZIP_IMPORT_DIR: 'lastZipImportDir',\n  LAST_AUDIO_ZIP_IMPORT_DIR: 'lastAudioZipImportDir',\n  LAST_MULTI_AUDIO_IMPORT_DIR: 'lastMultiAudioImportDir',\n  LAST_MULTI_ZIP_IMPORT_DIR: 'lastMultiZipImportDir',\n  LAST_MULTI_AUDIO_ZIP_IMPORT_DIR: 'lastMultiAudioZipImportDir',\n  LAST_MEDIA_LIBRARY_IMPORT_DIR: 'lastMediaLibraryImportDir',\n  LAST_SD_REFERENCE_IMAGE_DIR: 'lastSdReferenceImageDir',\n  LAST_COMFY_WORKFLOW_API_DIR: 'lastComfyWorkflowApiDir',\n  LAST_COMFY_WORKFLOW_CONFIG_DIR: 'lastComfyWorkflowConfigDir',\n  RECENT_PROJECTS: 'recentProjects',\n  MEDIA_SUBSCRIPTIONS_REGISTRY: 'storyStudio.mediaSubscriptionsRegistry',\n  MEDIA_SUBSCRIPTIONS_REGISTRY_BACKUP: 'storyStudio.mediaSubscriptionsRegistry.unreadableBackup',\n  MEDIA_TAGS_VERSION: 'mediaTagsVersion',\n  UI_LANGUAGE: 'storyStudio.uiLanguage',\n  THEME: 'storyStudioThemePreference',\n  SELECTION_OPENS_SETTINGS: 'storyStudio.selectionOpensSettings',\n  VERBOSE_LOGGING: 'storyStudio.verboseLogging',\n  PACK_LEADING_SILENCE_SECONDS: 'storyStudio.packLeadingSilenceSeconds',\n  PACK_TRAILING_SILENCE_SECONDS: 'storyStudio.packTrailingSilenceSeconds',\n  XTTS_SETTINGS: 'xttsSettings',\n  SD_SETTINGS: 'sdSettings',\n  KEYBOARD_SHORTCUTS: 'storyStudioKeyboardShortcuts',\n  SD_RESULTS: 'sdJobResults',\n  MEDIA_METADATA_PREFIX: 'ss-meta-v2:',\n  AUDIO_ASSEMBLY_OPTIONS: 'audio-assembly-opts',\n  DIAGRAM_SHOW_TREE: 'diagramShowTree',\n  DIAGRAM_SHOW_SETTINGS: 'diagramShowSettings',\n  DIAGRAM_SHOW_DIAGRAM: 'diagramShowDiagram',\n  WORKSPACE_PANEL_ORDER: 'workspacePanelOrder',\n  SETTINGS_PANEL_WIDTH: 'settingsPanelWidth',\n  TREE_PANEL_WIDTH: 'treePanelWidth',\n  ADVANCED_WORKSPACE_PANEL_ORDER: 'advancedWorkspacePanelOrder',\n  ADVANCED_SHOW_NODE_LIST: 'advancedShowNodeList',\n  ADVANCED_SHOW_INSPECTOR: 'advancedShowInspector',\n  ADVANCED_SHOW_OVERVIEW: 'advancedShowOverview',\n  ADVANCED_NODE_LIST_PANEL_WIDTH: 'advancedNodeListPanelWidth',\n  ADVANCED_INSPECTOR_PANEL_WIDTH: 'advancedInspectorPanelWidth',\n  ADVANCED_NEW_STAGE_CONTROLS: 'advancedNewStageControls',\n  FLOW_DIAGRAM_SHOW_RETURNS: 'fd_show_returns',\n  TREE_SHOW_DEFAULT_NAVIGATION_BADGES: 'tree_show_default_navigation_badges',\n  TREE_SHOW_GUIDES: 'tree_show_guides',\n  XTTS_LAST_VOICE: 'xtts_last_voice',\n  XTTS_LAST_SPEAKER: 'xtts_last_speaker',\n  PIPER_LAST_VOICE: 'piper_last_voice',\n  YOUTUBE_CGU_ACCEPTED: 'storyStudio.youtubeCguAccepted',\n  YTDLP_CUSTOM_PATH: 'storyStudio.ytDlpCustomPath',\n  SIMPLE_MODE_INFO_DISMISS: 'storyStudio.simpleModeInfoDismissed',\n  FREE_BOTTOM_PANEL_HEIGHT: 'storyStudio.free.bottomPanelHeight',\n  ADVANCED_BOTTOM_PANEL_HEIGHT: 'storyStudio.advanced.bottomPanelHeight',\n  FREE_FLOATING_SIMULATOR_GEOMETRY: 'storyStudio.free.floatingSimulatorGeometry',\n  ADVANCED_FLOATING_SIMULATOR_GEOMETRY: 'storyStudio.advanced.floatingSimulatorGeometry',\n  MEDIA_EXPLORER_COL_WIDTHS: 'me-col-widths-v2',\n  MEDIA_EXPLORER_VISIBLE_COLS: 'me-visible-cols-v2',\n  AI_QUEUE_COL_WIDTHS: 'aiq-col-widths-v1',\n});\n\nexport const EDITOR_LAYOUT_SCOPE = Object.freeze({\n  FREE: 'free',\n  ADVANCED: 'advanced',\n});\n\nconst EDITOR_LAYOUT_KEYS = Object.freeze({\n  [EDITOR_LAYOUT_SCOPE.FREE]: Object.freeze({\n    panelOrder: KEYS.WORKSPACE_PANEL_ORDER,\n    primaryPanelWidth: KEYS.TREE_PANEL_WIDTH,\n    secondaryPanelWidth: KEYS.SETTINGS_PANEL_WIDTH,\n    bottomPanelOpen: KEYS.FREE_BOTTOM_PANEL_OPEN,\n    bottomPanelTab: KEYS.FREE_BOTTOM_PANEL_TAB,\n    bottomPanelHeight: KEYS.FREE_BOTTOM_PANEL_HEIGHT,\n    floatingSimulatorGeometry: KEYS.FREE_FLOATING_SIMULATOR_GEOMETRY,\n  }),\n  [EDITOR_LAYOUT_SCOPE.ADVANCED]: Object.freeze({\n    panelOrder: KEYS.ADVANCED_WORKSPACE_PANEL_ORDER,\n    primaryPanelWidth: KEYS.ADVANCED_NODE_LIST_PANEL_WIDTH,\n    secondaryPanelWidth: KEYS.ADVANCED_INSPECTOR_PANEL_WIDTH,\n    bottomPanelOpen: KEYS.ADVANCED_BOTTOM_PANEL_OPEN,\n    bottomPanelTab: KEYS.ADVANCED_BOTTOM_PANEL_TAB,\n    bottomPanelHeight: KEYS.ADVANCED_BOTTOM_PANEL_HEIGHT,\n    floatingSimulatorGeometry: KEYS.ADVANCED_FLOATING_SIMULATOR_GEOMETRY,\n  }),\n});\n\nexport function editorLayoutKeys(scope) {\n  const keys = EDITOR_LAYOUT_KEYS[scope];\n  if (!keys) throw new Error(`Périmètre de disposition inconnu : ${scope}`);\n  return keys;\n}\n\nconst LEGACY_BOTTOM_PANEL_KEYS = Object.freeze({\n  bottomPanelOpen: 'bottomPanelOpen',\n  bottomPanelTab: 'bottomPanelTab',\n  bottomPanelHeight: 'bottomPanelHeight',\n});\nconst EDITOR_LAYOUT_MIGRATION_APPLIED = 'storyStudio.editorLayoutMigrationApplied';\n\nfunction storage() {\n  return typeof window !== 'undefined' ? window.localStorage : globalThis.localStorage;\n}\n\nexport function read(key, { defaultValue = null, parse } = {}) {\n  try {\n    const value = storage()?.getItem(key);\n    if (value == null) return defaultValue;\n    return parse ? parse(value) : value;\n  } catch {\n    return defaultValue;\n  }\n}\n\n/** Écrit une valeur ; rend `false` si le stockage local la refuse (quota, accès). */\nexport function write(key, value, { serialize } = {}) {\n  try {\n    const target = storage();\n    if (!target) return false;\n    target.setItem(key, serialize ? serialize(value) : value);\n    return true;\n  } catch {\n    return false;\n  }\n}\n\nexport function remove(key) {\n  try {\n    storage()?.removeItem(key);\n  } catch {}\n}\n\n// Détecter avant les migrations, qui écrivent leurs réglages par défaut.\nexport function hasExistingSettings() {\n  return Object.values(KEYS).some((key) => read(key) != null);\n}\n\n// Migrations ponctuelles des réglages persistés, appelées au boot (main.jsx)\n// avant le montage de l'app.\nexport function runSettingsMigrations() {\n  remove('showCentralDiagram');\n  remove('fd_auto_open_settings');\n  remove('fd_inspector_width');\n\n  // Vague 2 : la machine « ferme/colonne/plein » + slot gauche est remplacée par\n  // 3 bascules de panneaux indépendantes (showTree/showSettings/showDiagram, dont\n  // les défauts sont fournis par useWorkspaceViewState). La vue n'est pas une donnée\n  // projet : on purge simplement les clés de l'ancien modèle, sans migrer de valeur.\n  remove('diagramViewState');\n  remove('diagramLastOpenState');\n  remove('diagramPleinLeftSlot');\n  remove('diagramSettingsSlotWidth');\n  remove('diagramColumnWidth');\n\n  // L'enregistrement automatique devient actif par défaut.\n  // `usePersistentState` a toujours écrit la valeur par défaut dès le montage,\n  // donc un 'false' stocké ne distingue pas un choix explicite d'un défaut\n  // hérité : bascule one-shot vers 'true'. Désactiver ensuite reste respecté.\n  if (read(KEYS.AUTOSAVE_DEFAULT_ON_APPLIED) == null) {\n    write(KEYS.AUTOSAVE_ENABLED, 'true');\n    write(KEYS.AUTOSAVE_DEFAULT_ON_APPLIED, '1');\n  }\n\n  // Avant 0.9.9, le panneau inférieur était commun aux deux éditeurs.\n  // Dupliquer ses trois valeurs préserve exactement la disposition existante\n  // au premier démarrage, puis le marqueur empêche toute resynchronisation :\n  // les deux surfaces peuvent ensuite diverger sans s'écraser.\n  if (read(EDITOR_LAYOUT_MIGRATION_APPLIED) == null) {\n    const scopes = [EDITOR_LAYOUT_SCOPE.FREE, EDITOR_LAYOUT_SCOPE.ADVANCED];\n    for (const field of Object.keys(LEGACY_BOTTOM_PANEL_KEYS)) {\n      const legacyKey = LEGACY_BOTTOM_PANEL_KEYS[field];\n      const legacyValue = read(legacyKey);\n      if (legacyValue != null) {\n        for (const scope of scopes) {\n          const targetKey = editorLayoutKeys(scope)[field];\n          if (read(targetKey) == null) write(targetKey, legacyValue);\n        }\n      }\n      remove(legacyKey);\n    }\n    write(EDITOR_LAYOUT_MIGRATION_APPLIED, '1');\n  }\n}\n",
  "src/store/sdSettings.js": "import { KEYS, read as readSetting, write as writeSetting } from './persistentSettings.js';\n\nconst DEFAULT_SD_SETTINGS = {\n  serverUrl: 'http://127.0.0.1:8188',\n  autoStart: false,\n  launcherPath: '',\n  aiImageGen: false,\n};\n\nexport function loadSdSettings() {\n  try {\n    const raw = readSetting(KEYS.SD_SETTINGS);\n    if (!raw) return { ...DEFAULT_SD_SETTINGS };\n    const parsed = JSON.parse(raw);\n    const { batPath, ...portable } = parsed;\n    return {\n      ...DEFAULT_SD_SETTINGS,\n      ...portable,\n      launcherPath: Object.hasOwn(portable, 'launcherPath')\n        ? portable.launcherPath\n        : (batPath ?? ''),\n    };\n  } catch {\n    return { ...DEFAULT_SD_SETTINGS };\n  }\n}\n\nexport function saveSdSettings(settings) {\n  const portable = { ...(settings ?? {}) };\n  delete portable.batPath;\n  writeSetting(KEYS.SD_SETTINGS, JSON.stringify({\n    ...DEFAULT_SD_SETTINGS,\n    ...portable,\n  }));\n}\n",
  "src/store/themePreference.js": "import { KEYS, read as readSetting, write as writeSetting } from './persistentSettings';\n\nexport const THEME_OPTIONS = [\n  { value: 'system', labelKey: 'settings:interface.theme.system' },\n  { value: 'dark', labelKey: 'settings:interface.theme.dark' },\n  { value: 'light', labelKey: 'settings:interface.theme.light' },\n];\n\nconst DARK_QUERY = '(prefers-color-scheme: dark)';\n\nexport function loadThemePreference() {\n  try {\n    const value = readSetting(KEYS.THEME);\n    return THEME_OPTIONS.some((option) => option.value === value) ? value : 'system';\n  } catch {\n    return 'system';\n  }\n}\n\nexport function saveThemePreference(value) {\n  try {\n    writeSetting(KEYS.THEME, value);\n  } catch {}\n}\n\nfunction getSystemTheme() {\n  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return 'light';\n  return window.matchMedia(DARK_QUERY).matches ? 'dark' : 'light';\n}\n\nfunction resolveThemePreference(value) {\n  return value === 'dark' || value === 'light' ? value : getSystemTheme();\n}\n\nexport function applyThemePreference(value) {\n  if (typeof document === 'undefined') return;\n  const preference = value === 'dark' || value === 'light' ? value : 'system';\n  const root = document.documentElement;\n\n  function applyResolvedTheme() {\n    const resolved = resolveThemePreference(preference);\n    if (preference === 'dark' || preference === 'light') {\n      root.dataset.theme = preference;\n    } else if (resolved === 'dark') {\n      root.dataset.theme = 'dark';\n    } else {\n      delete root.dataset.theme;\n    }\n    root.style.colorScheme = resolved;\n  }\n\n  applyResolvedTheme();\n\n  if (preference !== 'system' || typeof window === 'undefined' || typeof window.matchMedia !== 'function') {\n    return undefined;\n  }\n\n  const media = window.matchMedia(DARK_QUERY);\n  if (typeof media.addEventListener === 'function') {\n    media.addEventListener('change', applyResolvedTheme);\n  } else {\n    media.addListener?.(applyResolvedTheme);\n  }\n\n  return () => {\n    if (typeof media.removeEventListener === 'function') {\n      media.removeEventListener('change', applyResolvedTheme);\n    } else {\n      media.removeListener?.(applyResolvedTheme);\n    }\n  };\n}\n",
  "src/store/xttsSettings.js": "import { KEYS, read as readSetting, write as writeSetting } from './persistentSettings.js';\n\n// Voix Piper par défaut — doit correspondre au catalogue Rust\n// (`services/piper/catalog.rs`).\nexport const PIPER_DEFAULT_VOICE = 'fr_FR-siwis-medium';\nexport const PIPER_DEFAULT_LANGUAGE = 'fr_FR';\n\nexport const PIPER_LANGUAGE_OPTIONS = [\n  { value: 'fr_FR', label: 'Français', defaultVoice: PIPER_DEFAULT_VOICE },\n  { value: 'en_GB', label: 'English UK', defaultVoice: 'en_GB-jenny_dioco-medium' },\n  { value: 'en_US', label: 'English US', defaultVoice: 'en_US-kristin-medium' },\n  { value: 'it_IT', label: 'Italiano', defaultVoice: 'it_IT-serena-medium' },\n];\n\nexport function piperDefaultVoiceForLanguage(voices, language) {\n  const catalogDefault = voices.find((voice) => voice.language === language && voice.isDefault);\n  if (catalogDefault) return catalogDefault.id;\n  const configuredDefault = PIPER_LANGUAGE_OPTIONS.find((option) => option.value === language)?.defaultVoice;\n  return configuredDefault || PIPER_DEFAULT_VOICE;\n}\n\nexport function piperLanguageForVoice(voices, voiceId, fallback = PIPER_DEFAULT_LANGUAGE) {\n  return voices.find((voice) => voice.id === voiceId)?.language || fallback;\n}\n\nconst DEFAULT_XTTS_SETTINGS = {\n  // Moteur TTS actif. Piper est le défaut zéro-config ; XTTS reste\n  // opt-in pour les avancés (clonage de voix, qualité max).\n  backend: 'piper',\n  enabled: false,\n  serverUrl: 'http://127.0.0.1:8020',\n  xttsDir: '',\n  autoStart: true,\n  forceCpu: false,\n  language: 'fr',\n  favoriteVoices: [],\n  // Réglages Piper.\n  piperLanguage: PIPER_DEFAULT_LANGUAGE,\n  piperVoice: PIPER_DEFAULT_VOICE,\n  piperSpeed: 1.0,\n};\n\nfunction withoutLegacyPiperSettings(settings) {\n  const portable = { ...(settings ?? {}) };\n  delete portable.piperSentenceSilence;\n  if (portable.piperVoice === 'fr_FR-gilles-low') {\n    portable.piperLanguage = PIPER_DEFAULT_LANGUAGE;\n    portable.piperVoice = PIPER_DEFAULT_VOICE;\n  }\n  return portable;\n}\n\nexport function loadXttsSettings() {\n  try {\n    const raw = readSetting(KEYS.XTTS_SETTINGS);\n    if (!raw) return { ...DEFAULT_XTTS_SETTINGS };\n    const parsed = {\n      ...DEFAULT_XTTS_SETTINGS,\n      ...withoutLegacyPiperSettings(JSON.parse(raw)),\n    };\n    const piperLanguage = PIPER_LANGUAGE_OPTIONS.some(({ value }) => value === parsed.piperLanguage)\n      ? parsed.piperLanguage\n      : PIPER_DEFAULT_LANGUAGE;\n    return {\n      ...parsed,\n      piperLanguage,\n      favoriteVoices: Array.isArray(parsed.favoriteVoices) ? parsed.favoriteVoices : [],\n    };\n  } catch {\n    return { ...DEFAULT_XTTS_SETTINGS };\n  }\n}\n\nexport function saveXttsSettings(settings) {\n  writeSetting(KEYS.XTTS_SETTINGS, JSON.stringify({\n    ...DEFAULT_XTTS_SETTINGS,\n    ...withoutLegacyPiperSettings(settings),\n  }));\n}\n\n// Le bouton TTS est disponible quand Piper est actif (zéro-config, toujours\n// dispo) ou quand XTTS a été explicitement activé. Centralise la condition\n// d'affichage du bouton « Générer une voix ».\nexport function isTtsAvailable(settings) {\n  if (!settings) return false;\n  return settings.backend === 'piper' || settings.enabled === true;\n}\n\n// La voix d'une génération groupée d'audios titres, sans fenêtre à ouvrir :\n// Piper a toujours une voix par défaut ; XTTS reprend la dernière voix choisie,\n// ou la première favorite. Vide si l'auteur n'en a encore choisi aucune.\n// Partagée par la sélection multiple des deux éditeurs.\nexport function batchTitleVoice(settings) {\n  if ((settings?.backend || 'piper') === 'piper') {\n    return settings?.piperVoice || readSetting(KEYS.PIPER_LAST_VOICE) || PIPER_DEFAULT_VOICE;\n  }\n  const favoriteVoices = Array.isArray(settings?.favoriteVoices) ? settings.favoriteVoices : [];\n  return (\n    readSetting(KEYS.XTTS_LAST_VOICE)\n    || readSetting(KEYS.XTTS_LAST_SPEAKER)\n    || favoriteVoices[0]\n    || ''\n  );\n}\n"
};

